Problem:
An ice cream company sells ice cream as cones and tubs. A cone of ice cream contains 3 oz of ice cream while a tub contains 24 oz of ice cream.  Due to the recent wave of heat and a recent promotion, the company expects to sell at least 2 times more cones than tubs of ice cream. However, to reduce labour time and looking at previous sales, management decided to require stores to at least create 30 tubs of ice cream. If the company has the capacity to make 5000 oz of ice cream, how many orders of each should be made to maximize the total number of sales of ice cream?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "cones",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "tubs",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "cones",
     "coef": 1.0
    },
    {
     "var": "tubs",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "cones_at_least_2x_tubs",
    "terms": [
     {
      "var": "cones",
      "coef": 1.0
     },
     {
      "var": "tubs",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "min_tubs",
    "terms": [
     {
      "var": "tubs",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 30.0
   },
   {
    "name": "capacity_oz",
    "terms": [
     {
      "var": "cones",
      "coef": 3.0
     },
     {
      "var": "tubs",
      "coef": 24.0
     }
    ],
    "sense": "<=",
    "rhs": 5000.0
   }
  ]
 },
 "facts": {
  "objective": 1456.0,
  "values": {
   "cones": 1426.0,
   "tubs": 30.0
  },
  "binding": [
   "min_tubs"
  ],
  "slack": {
   "cones_at_least_2x_tubs": 1366.0,
   "min_tubs": 0.0,
   "capacity_oz": 2.0
  },
  "shadow_prices": null,
  "limits": {
   "cones_at_least_2x_tubs": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "min_tubs": {
    "dropped_improves": true,
    "loosened_improves": true
   },
   "capacity_oz": {
    "dropped_improves": true,
    "loosened_improves": true
   }
  }
 }
}
